import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Screener ensemble: CLV, peer lead-lag, reversal, risk-adjusted momentum.
FACTOR_WEIGHTS = {"clv": 0.3396, "peer": 0.2612, "reversal": 0.2012, "momentum": 0.1980}
MIN_W, MAX_W = 0.015, 0.16
bar_count = 0


def cs_rank(values):
    out = {s: 0.5 for s in UNIVERSE}
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    if len(valid) < 2:
        return out
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / len(valid)
    return out


def box_simplex(raw):
    # Iterative projection to non-negative, full-investment weights with sensible
    # 15-asset concentration limits.
    w = {s: max(float(raw.get(s, 0.0)), 1e-12) for s in UNIVERSE}
    w = {s: x / sum(w.values()) for s, x in w.items()}
    fixed = {}
    for _ in range(40):
        changed = False
        for s in UNIVERSE:
            if s in fixed:
                continue
            if w[s] < MIN_W:
                fixed[s] = MIN_W; w[s] = MIN_W; changed = True
            elif w[s] > MAX_W:
                fixed[s] = MAX_W; w[s] = MAX_W; changed = True
        free = [s for s in UNIVERSE if s not in fixed]
        if not changed:
            break
        remaining = 1.0 - sum(fixed.values())
        base = sum(w[s] for s in free)
        if free and base > 0:
            for s in free:
                w[s] = remaining * w[s] / base
    total = sum(w.values())
    return {s: float(w[s] / total) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global bar_count
    bar_count += 1
    account = get_account_dict()
    positions = {p.get("symbol"): p for p in account.get("positions", [])}
    # The first allocation is mandatory; thereafter decisions are one per
    # ten simulator trading days.  A complete target is always submitted.
    invested = any(float(p.get("quantity", 0)) > 0 for p in positions.values())
    if invested and (bar_count - 1) % 10 != 0:
        return

    market = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=90)
        if df is None or len(df) < 25:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], dtype=float)
        h = np.asarray(df["high"], dtype=float)
        l = np.asarray(df["low"], dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        if len(c) >= 22:
            market[s] = (c, h, l, r)
    if len(market) < 12:
        return

    clv, peer_base, reversal, momentum, invvol = {}, {}, {}, {}, {}
    for s, (c, h, l, r) in market.items():
        # One-day close-location value, with rank normalization providing
        # cross-sectional winsorization.
        clv[s] = float((2.0 * c[-1] - h[-1] - l[-1]) / max(h[-1] - l[-1], 1e-12))
        reversal[s] = float(-np.mean(r[-5:]))
        vol = max(float(np.std(r[-20:])), 0.008)
        invvol[s] = 1.0 / vol
        momentum[s] = float((c[-1] / max(c[-21], 1e-12) - 1.0) / (vol + 0.01))
        peer_base[s] = float(c[-1] / max(c[-6], 1e-12) - 1.0)
    median_peer = float(np.median(list(peer_base.values())))
    peer = {s: v - median_peer for s, v in peer_base.items()}
    ranked = {k: cs_rank(v) for k, v in {
        "clv": clv, "peer": peer, "reversal": reversal, "momentum": momentum
    }.items()}
    score = {s: sum(FACTOR_WEIGHTS[k] * ranked[k][s] for k in ranked) for s in UNIVERSE}

    # Medium-high bearish/sideways regime: remain fully invested but shift
    # score toward tradable defensive benchmarks rather than cash.
    spx = market.get("SPX")
    if spx is not None:
        c = spx[0]
        if c[-1] < c[-21] and c[-1] < c[-6]:
            for s in ("XAU", "US10Y", "CN10Y"):
                score[s] += 0.18
            for s in ("BTC", "ETH", "WTI"):
                score[s] = max(0.05, score[s] - 0.10)

    mean_invvol = float(np.mean(list(invvol.values())))
    raw = {s: max(score[s], 0.01) * (0.78 + 0.22 * invvol.get(s, mean_invvol) / mean_invvol) for s in UNIVERSE}
    rebalance_to_weights(box_simplex(raw))

